<?php
namespace App\Models; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class PosReceipt extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','register_id','shift_id','customer_id','cashier_id','number','state','subtotal','tax_total','total','idempotency_key']; protected function casts():array{return ['subtotal'=>'decimal:6','tax_total'=>'decimal:6','total'=>'decimal:6'];} public function register(){return $this->belongsTo(PosRegister::class,'register_id');} public function shift(){return $this->belongsTo(PosShift::class,'shift_id');} public function customer(){return $this->belongsTo(Customer::class,'customer_id');} public function items(){return $this->hasMany(PosReceiptItem::class,'receipt_id');} public function payments(){return $this->hasMany(PosReceiptPayment::class,'receipt_id');} }
